/**
 * Data for the in-game page „Credits & Lizenzen“ / "Credits & licences" (no UI here: the pause
 * menu team owns the page). Robot rows are generated by tools/robots/build.mjs
 * (src/robots/credits.ts); software and fonts are listed here and checked against the bundle by
 * the build (tools/notices-plugin.mjs writes dist/THIRD-PARTY-NOTICES.txt from the same modules).
 *
 * Usage (lazy, so none of it is in the first load):
 *
 *   const { CREDITS, creditHref } = await import('@/core/credits');
 *   panel.title = CREDITS.title[lang];
 *   panel.text(CREDITS.intro[lang]); panel.text(CREDITS.disclaimer[lang]); panel.text(CREDITS.unitree[lang]);
 *   for (const r of CREDITS.robots)                     // one row per robot model
 *     panel.row(r.name[lang], r.attribution[lang], r.changes[lang], creditHref(r.licenseFiles[0]));
 *   for (const s of CREDITS.software) panel.row(s.name, `${s.license} · ${s.copyright}`, creditHref(s.licenseFile));
 *   for (const f of CREDITS.fonts) panel.row(f.name, `${f.license} · ${f.copyright}`, creditHref(f.licenseFile));
 *   panel.link(CREDITS.labels.allNotices[lang], creditHref(CREDITS.noticesFile));
 * Every link is same-origin (dist/licenses/…, dist/THIRD-PARTY-NOTICES.txt): no third-party request.
 * The amber robot models are listed only in a build that ships them (VITE_AMBER=1, src/core/release.ts).
 */
import { assetUrl } from './Assets';
import { SHOW_AMBER } from './release';
import { ROBOT_CREDITS, type RobotCredit } from '@/robots/credits';

type Text = { readonly de: string; readonly en: string };

export interface SoftwareCredit {
  readonly name: string;
  readonly license: string;
  readonly copyright: string;
  readonly url: string;
  /** same-origin licence text (credits link) */
  readonly licenseFile: string;
}

export interface FontCredit {
  readonly name: string;
  readonly license: string;
  readonly copyright: string;
  readonly url: string;
  readonly licenseFile: string;
}

export type { RobotCredit };

